describe("extension MCP vocabulary", () => {
  it("uses literal canonical Lodestar verbs with explicit discriminators", () => {
    const violations: string[] = [];

    const files = readdirSync(__dirname).filter(
      (fileName) => fileName.endsWith(".ts") && !fileName.endsWith(".test.ts")
    );
    for (const fileName of files) {
      const path = join(__dirname, fileName);
      const source = ts.createSourceFile(
        path,
        readFileSync(path, "utf8"),
        ts.ScriptTarget.Latest,
        true,
        ts.ScriptKind.TS
      );

      const visit = (node: ts.Node): void => {
        if (
          ts.isCallExpression(node) &&
          ts.isPropertyAccessExpression(node.expression) &&
          node.expression.name.text === "callTool"
        ) {
          inspectCall(
            fileName,
            node.expression.expression.getText(source),
            source,
            node,
            violations
          );
        }
        ts.forEachChild(node, visit);
      };
      visit(source);
    }

    expect(violations).toEqual([]);
  });
});

function inspectCall(
  fileName: string,
  receiver: string,
  source: ts.SourceFile,
  call: ts.CallExpression,
  violations: string[]
): void {
  const line = source.getLineAndCharacterOfPosition(call.getStart(source)).line + 1;
  const first = call.arguments[0];
  if (!first || !ts.isStringLiteral(first)) {
    violations.push(`${fileName}:${line} constructs a Lodestar tool name dynamically`);
    return;
  }

  const tool = first.text;
  if (`${fileName}:${receiver}:${tool}` === CURRENT_MINDLEAK_OVERLAP_CALL) {
    return;
  }
  if (RETIRED_LODESTAR_TOOLS.has(tool)) {
    violations.push(`${fileName}:${line} calls retired Lodestar tool ${tool}`);
    return;
  }

  const contract = DISCRIMINATORS[tool];
  if (!contract) {
    return;
  }
  const args = call.arguments[1];
  if (!args || !ts.isObjectLiteralExpression(args)) {
    violations.push(`${fileName}:${line} calls ${tool} without a literal argument object`);
    return;
  }
  const property = args.properties.find(
    (candidate): candidate is ts.PropertyAssignment =>
      ts.isPropertyAssignment(candidate) && candidate.name.getText(source) === contract.key
  );
  if (!property) {
    violations.push(`${fileName}:${line} calls ${tool} without ${contract.key}`);
    return;
  }
  if (ts.isStringLiteral(property.initializer) && !contract.values.has(property.initializer.text)) {
    violations.push(
      `${fileName}:${line} calls ${tool} with unknown ${contract.key}=${property.initializer.text}`
    );
  }
}
